            <tr><td className="px-3 py-2 text-xs">北海道</td><td className="px-3 py-2 text-xs">北海道</td><td className="px-3 py-2 text-xs">新ひだか町 住宅街</td><td className="px-3 py-2 text-xs">小学生男児が体長1.2mのクマを目撃</td><td className="px-3 py-2 text-xs">（※4）</td></tr>
